const body = $input.first().json;
const eventType = body.type || 'email.unknown';
const data = body.data || {};
const recipient = Array.isArray(data.to) ? data.to[0] : (data.to || 'unknown');
const subject = data.subject || 'No Subject';
const emailId = data.email_id || data.id || '';
const createdAt = data.created_at || new Date().toISOString();

return [{
  json: {
    event_type: eventType.replace('.', '_'),
    raw_type: eventType,
    recipient: recipient.toLowerCase(),
    subject: subject,
    email_id: emailId,
    created_at: createdAt,
    posthog_payload: {
      api_key: "phc_nyTy8YcAKX2XGhqS5dGjP65kK5MSgQdKcRAXNjZKmWEu",
      event: `resend_${eventType.replace('.', '_')}`,
      distinct_id: recipient.toLowerCase(),
      properties: {
        email_subject: subject,
        resend_email_id: emailId,
        event_time: createdAt,
        channel: "resend_email"
      }
    }
  }
}];
